        cookies = flask.Request.cookies.__get__(self)

        result = {}
        desuffixed = {}
        for key, value in cookies.items():
            if key.endswith(self.cookie_suffix):
                desuffixed[key[: -len(self.cookie_suffix)]] = value
            else:
                result[key] = value

