        self.session_store = SessionStore()





        self.inbound_group_store = GroupSessionStore()










        self.outbound_group_sessions = {}

        self.tracked_users = set()



        self.outgoing_key_requests = dict()




        self.received_key_requests = dict()







        self.key_requests_waiting_for_session = defaultdict(
            dict
        )
        self.key_request_devices_no_session = list()






        self.key_request_from_untrusted = dict()






        self.wedged_devices = list()





        self.key_re_requests_events = defaultdict(
            list
        )



        self.key_verifications = dict()





        self.outgoing_to_device_messages = []





        self.message_index_store = LRUCache(self._message_index_store_size)

