                if password is not None:
                    can_login = check_password_hash(user.password_hash, password)
                elif token is not None and user.token_hash is not None:
                    can_login = check_password_hash(user.token_hash, token)
                else:
                    can_login = False

                if can_login:

                    token = Token(user=user.uuid, token=str(secrets.token_hex(16)))

                    db.session.add(token)
                    db.session.commit()

                    resp = redirect_response(redirect_url, redirect_type)

                    resp.set_cookie("auth_token", token.token, samesite="Lax")
                    resp.set_cookie("auth_username", username, samesite="Lax")

                    return resp

                else:
                    return jsonify({"error": invalid_login_msg}), 401

    @app.route("/login/users", methods=["DELETE"])
    def delete_user() -> Union[
        Tuple[Literal[""], Literal[401]],
        Tuple[Response, Literal[500]],
        Tuple[Response, Literal[405]],
        Literal[""],
    ]:
        if not is_authenticated(request):
            return "", 401

        self_username = request.cookies.get("auth_username")
        if "username" in request.form:
            to_delete_username = request.form.get("username")

            user = User.query.filter(User.username == to_delete_username).first()
            if user is not None:
                if user.is_admin:
                    return jsonify({"error": "Admins cannot be deleted."}), 500
                elif self_username == to_delete_username:
                    return jsonify({"error": "Deleting own user is not allowed."}), 405
                else:
                    db.session.delete(user)
                    db.session.commit()
                    return ""
            else:
                return jsonify({"error": "User does not exist."}), 500
        else:
            return jsonify({"error": "No username supplied."}), 500

    @app.route("/login/users", methods=["POST"])
    def add_user() -> Union[
        Tuple[Literal[""], Literal[401]],
        Tuple[Response, Literal[409]],
        Tuple[Response, Literal[400]],
        Literal[""],
    ]:
        if not is_authenticated(request):
            return "", 401

        if "username" in request.form:

            username = request.form.get("username")
            password = request.form.get("password")

            if username == app.config.get("ORCHEST_CLOUD_RESERVED_USER"):
                return jsonify({"error": "User is reserved."}), 409

            if len(password) == 0:
                return jsonify({"error": "Password cannot be empty."}), 400

            user = User.query.filter(User.username == username).first()
            if user is not None:
                return jsonify({"error": "User already exists."}), 409

            user = User(
                username=username,
                password_hash=generate_password_hash(password),
                uuid=str(uuid.uuid4()),
            )

            db.session.add(user)
            db.session.commit()
            return ""
        else:
            return jsonify({"error": "No username supplied."}), 400

    @app.route("/login/users", methods=["GET"])
    def get_users() -> Tuple[Literal[""], Literal[401]] | Tuple[Response, Literal[200]]:
        if not is_authenticated(request):
            return "", 401

        data_json: Dict[
            Literal["users"],
            List[Dict[Literal["username"], str]],
        ] = {"users": []}
        users = User.query.all()
        for user in users:
            if user.username != app.config.get("ORCHEST_CLOUD_RESERVED_USER"):
                data_json["users"].append({"username": user.username})

        return jsonify(data_json), 200

    @app.route("/auth/service", methods=["GET"])
    def auth_service() -> Union[
        Tuple[Literal[""], Literal[200]],
        Tuple[Literal[""], Literal[401]],
    ]:
        global _auth_cache, _auth_cache_age



        if is_authenticated(request):
            return "", 200


        original_uri = request.headers.get("X-Original-URI")

        if original_uri is None:
            return "", 401

        try:



            components = original_uri.split("/")[1].split("_")[-2].split("-")
            session_uuid_prefix = components[-1]
            project_uuid_prefix = components[-2]
        except Exception:
            app.logger.error("Failed to parse X-Original-URI: %s" % original_uri)
            return "", 401

        auth_check = get_auth_cache(
            project_uuid_prefix, session_uuid_prefix, _auth_cache, _auth_cache_age
        )
        if auth_check["status"] == "available":
            if auth_check["requires_authentication"] is False:
                return "", 200
            else:
                return "", 401
        else:

            base_url = "http://%s/api/services/" % (app.config["ORCHEST_API_ADDRESS"])
            service_url = "%s?project_uuid_prefix=%s&session_uuid_prefix=%s" % (
                base_url,
                project_uuid_prefix,
                session_uuid_prefix,
            )

            try:
                r = requests.get(service_url)
                services = r.json().get("services", [])


                if len(services) == 0:
                    raise Exception("No services found")

                if len(services) > 1:
                    raise Exception(
                        "Filtered /api/services endpoint "
                        "should always return a single service"
                    )



                if services[0]["service"]["requires_authentication"] is False:
                    set_auth_cache(
                        project_uuid_prefix, session_uuid_prefix, False, _auth_cache
                    )
                    return "", 200
                else:
                    set_auth_cache(
                        project_uuid_prefix, session_uuid_prefix, True, _auth_cache
                    )
                    raise Exception("'requires_authentication' is not set to False")

            except Exception as e:
                app.logger.error(e)
                return "", 401

def make_return_stmt(stmt, context, begin_pos, _size, loop_memory_position=None):

    func_type = stmt.get_ancestor(vy_ast.FunctionDef)._metadata["type"]
    _, nonreentrant_post = get_nonreentrant_lock(func_type)

    if context.is_internal:
        if loop_memory_position is None:
            loop_memory_position = context.new_internal_variable(BaseType("uint256"))


        label_id = "_".join([str(x) for x in (context.method_id, stmt.lineno, stmt.col_offset)])
        exit_label = f"make_return_loop_exit_{label_id}"
        start_label = f"make_return_loop_start_{label_id}"



        if isinstance(begin_pos, int) and isinstance(_size, int):

            mloads = [["mload", pos] for pos in range(begin_pos, _size, 32)]
        else:
            mloads = [
                "seq_unchecked",
                ["mstore", loop_memory_position, _size],
                ["label", start_label],
                [
                    "if",
                    ["le", ["mload", loop_memory_position], 0],
                    ["goto", exit_label],
                ],
                [
                    "mload",
                    ["add", begin_pos, ["sub", ["mload", loop_memory_position], 32]],
                ],
                [
                    "mstore",
                    loop_memory_position,
                    ["sub", ["mload", loop_memory_position], 32],
                ],
                ["goto", start_label],
                ["label", exit_label],
            ]


        exit_repeater = ["exit_repeater"] if context.forvars else []

        return (
            ["seq_unchecked"]
            + exit_repeater
            + mloads
            + nonreentrant_post
            + [["jump", ["mload", context.callback_ptr]]]
        )
    else:
        return ["seq_unchecked"] + nonreentrant_post + [["return", begin_pos, _size]]
def gen_tuple_return(stmt, context, sub):
    abi_typ = abi_type_of(context.return_type)










    abi_typ = ensure_tuple(abi_typ)
    abi_bytes_needed = abi_typ.static_size() + abi_typ.dynamic_size_bound()
    dst = context.memory_allocator.expand_memory(abi_bytes_needed)
    return_buffer = LLLnode(
        dst, location="memory", annotation="return_buffer", typ=context.return_type
    )

    check_assign(return_buffer, sub, pos=getpos(stmt))

    if sub.value == "multi":

        if isinstance(context.return_type, TupleType) and not abi_typ.dynamic_size_bound():




            new_sub = LLLnode.from_list(
                context.new_internal_variable(context.return_type),
                typ=context.return_type,
                location="memory",
            )
            setter = make_setter(new_sub, sub, "memory", pos=getpos(stmt))
            return LLLnode.from_list(
                [
                    "seq",
                    setter,
                    make_return_stmt(
                        stmt, context, new_sub, get_size_of_type(context.return_type) * 32,
                    ),
                ],
                typ=None,
                pos=getpos(stmt),
            )



        encode_out = abi_encode(return_buffer, sub, pos=getpos(stmt), returns_len=True)
        load_return_len = ["mload", MemoryPositions.FREE_VAR_SPACE]
        os = [
            "seq",
            ["mstore", MemoryPositions.FREE_VAR_SPACE, encode_out],
            make_return_stmt(stmt, context, return_buffer, load_return_len),
        ]
        return LLLnode.from_list(os, typ=None, pos=getpos(stmt), valency=0)



    if sub.value == "seq_unchecked" and sub.args[-1].value == "multi":
        encode_out = abi_encode(return_buffer, sub.args[-1], pos=getpos(stmt), returns_len=True)
        load_return_len = ["mload", MemoryPositions.FREE_VAR_SPACE]
        os = (
            ["seq"]
            + sub.args[:-1]
            + [
                ["mstore", MemoryPositions.FREE_VAR_SPACE, encode_out],
                make_return_stmt(stmt, context, return_buffer, load_return_len),
            ]
        )
        return LLLnode.from_list(os, typ=None, pos=getpos(stmt), valency=0)




    sub_loc = LLLnode("sub_loc", typ=sub.typ, location=sub.location)
    encode_out = abi_encode(return_buffer, sub_loc, pos=getpos(stmt), returns_len=True)
    load_return_len = ["mload", MemoryPositions.FREE_VAR_SPACE]
    os = [
        "with",
        "sub_loc",
        sub,
        [
            "seq",
            ["mstore", MemoryPositions.FREE_VAR_SPACE, encode_out],
            make_return_stmt(stmt, context, return_buffer, load_return_len),
        ],
    ]
    return LLLnode.from_list(os, typ=None, pos=getpos(stmt), valency=0)
class Stmt:
    def __init__(self, node: vy_ast.VyperNode, context: Context) -> None:
        self.stmt = node
        self.context = context
        fn = getattr(self, f"parse_{type(node).__name__}", None)
        if fn is None:
            raise TypeCheckFailure(f"Invalid statement node: {type(node).__name__}")

        with context.internal_memory_scope():
            self.lll_node = fn()

        if self.lll_node is None:
            raise TypeCheckFailure("Statement node did not produce LLL")
    def parse_Expr(self):
        return Stmt(self.stmt.value, self.context).lll_node
    def parse_Pass(self):
        return LLLnode.from_list("pass", typ=None, pos=getpos(self.stmt))
    def parse_Name(self):
        if self.stmt.id == "vdb":
            return LLLnode("debugger", typ=None, pos=getpos(self.stmt))
        else:
            raise StructureException(f"Unsupported statement type: {type(self.stmt)}", self.stmt)
    def parse_AnnAssign(self):
        typ = parse_type(
            self.stmt.annotation, location="memory", custom_structs=self.context.structs,
        )
        varname = self.stmt.target.id
        pos = self.context.new_variable(varname, typ, pos=self.stmt)
        if self.stmt.value is None:
            return

        sub = Expr(self.stmt.value, self.context).lll_node

        is_literal_bytes32_assign = (
            isinstance(sub.typ, ByteArrayType)
            and sub.typ.maxlen == 32
            and isinstance(typ, BaseType)
            and typ.typ == "bytes32"
            and sub.typ.is_literal
        )


        if is_literal_bytes32_assign:
            sub = LLLnode(
                bytes_to_int(self.stmt.value.s), typ=BaseType("bytes32"), pos=getpos(self.stmt),
            )

        variable_loc = LLLnode.from_list(pos, typ=typ, location="memory", pos=getpos(self.stmt),)
        lll_node = make_setter(variable_loc, sub, "memory", pos=getpos(self.stmt))

        return lll_node
    def parse_Assign(self):

        sub = Expr(self.stmt.value, self.context).lll_node
        target = self._get_target(self.stmt.target)
        lll_node = make_setter(target, sub, target.location, pos=getpos(self.stmt))
        lll_node.pos = getpos(self.stmt)
        return lll_node
    def parse_If(self):
        if self.stmt.orelse:
            with self.context.block_scope():
                add_on = [parse_body(self.stmt.orelse, self.context)]
        else:
            add_on = []

        with self.context.block_scope():
            test_expr = Expr.parse_value_expr(self.stmt.test, self.context)
            body = ["if", test_expr, parse_body(self.stmt.body, self.context)] + add_on
            lll_node = LLLnode.from_list(body, typ=None, pos=getpos(self.stmt))
        return lll_node
    def parse_Log(self):
        event = self.stmt._metadata["type"]



        buf, _len = events.allocate_buffer_for_log(event, self.context)

        args = [Expr(arg, self.context).lll_node for arg in self.stmt.value.args]

        topic_lll = []
        data_lll = []
        for arg, is_indexed in zip(args, event.indexed):
            if is_indexed:
                topic_lll.append(arg)
            else:
                data_lll.append(arg)

        return events.lll_node_for_log(
            self.stmt, buf, _len, event, topic_lll, data_lll, self.context
        )
    def parse_Call(self):
        is_self_function = (
            (isinstance(self.stmt.func, vy_ast.Attribute))
            and isinstance(self.stmt.func.value, vy_ast.Name)
            and self.stmt.func.value.id == "self"
        )

        if isinstance(self.stmt.func, vy_ast.Name):
            funcname = self.stmt.func.id
            return STMT_DISPATCH_TABLE[funcname].build_LLL(self.stmt, self.context)
        elif is_self_function:
            return self_call.make_call(self.stmt, self.context)
        else:
            return external_call.make_external_call(self.stmt, self.context)
    def _assert_reason(self, test_expr, msg):
        if isinstance(msg, vy_ast.Name) and msg.id == "UNREACHABLE":
            return LLLnode.from_list(["assert_unreachable", test_expr], typ=None, pos=getpos(msg))

        reason_str_type = ByteArrayType(len(msg.value.strip()))

        sig_placeholder = self.context.new_internal_variable(BaseType(32))
        arg_placeholder = self.context.new_internal_variable(BaseType(32))
        placeholder_bytes = Expr(msg, self.context).lll_node

        method_id = fourbytes_to_int(keccak256(b"Error(string)")[:4])

        revert_seq = [
            "seq",
            ["mstore", sig_placeholder, method_id],
            ["mstore", arg_placeholder, 32],
            placeholder_bytes,
            ["revert", sig_placeholder + 28, int(4 + get_size_of_type(reason_str_type) * 32)],
        ]
        if test_expr:
            lll_node = ["if", ["iszero", test_expr], revert_seq]
        else:
            lll_node = revert_seq

        return LLLnode.from_list(lll_node, typ=None, pos=getpos(self.stmt))
    def parse_Assert(self):
        test_expr = Expr.parse_value_expr(self.stmt.test, self.context)
        if test_expr.typ.is_literal:
            if test_expr.value == 1:

                return LLLnode.from_list(["pass"], typ=None, pos=getpos(self.stmt))
            else:
                test_expr = test_expr.value

        if self.stmt.msg:
            return self._assert_reason(test_expr, self.stmt.msg)
        else:
            return LLLnode.from_list(["assert", test_expr], typ=None, pos=getpos(self.stmt))
    def parse_Raise(self):
        if self.stmt.exc:
            return self._assert_reason(0, self.stmt.exc)
        else:
            return LLLnode.from_list(["revert", 0, 0], typ=None, pos=getpos(self.stmt))
    def _check_valid_range_constant(self, arg_ast_node, raise_exception=True):
        with self.context.range_scope():

            arg_expr = Expr.parse_value_expr(arg_ast_node, self.context)

        is_integer_literal = (
            isinstance(arg_expr.typ, BaseType)
            and arg_expr.typ.is_literal
            and arg_expr.typ.typ in {"uint256", "int256"}
        )
        if not is_integer_literal and raise_exception:
            raise StructureException(
                "Range only accepts literal (constant) values of type uint256 or int256",
                arg_ast_node,
            )
        return is_integer_literal, arg_expr
    def _get_range_const_value(self, arg_ast_node):
        _, arg_expr = self._check_valid_range_constant(arg_ast_node)
        return arg_expr.value
    def parse_For(self):
        with self.context.block_scope():
            if self.stmt.get("iter.func.id") == "range":
                return self._parse_For_range()
            else:
                return self._parse_For_list()
    def _parse_For_range(self):



        iter_typ = "int256"
        if "type" in self.stmt.target._metadata:
            iter_typ = self.stmt.target._metadata["type"]._id


        arg0 = self.stmt.iter.args[0]
        num_of_args = len(self.stmt.iter.args)


        if num_of_args == 1:
            arg0_val = self._get_range_const_value(arg0)
            start = LLLnode.from_list(0, typ=iter_typ, pos=getpos(self.stmt))
            rounds = arg0_val


        elif self._check_valid_range_constant(self.stmt.iter.args[1], raise_exception=False)[0]:
            arg0_val = self._get_range_const_value(arg0)
            arg1_val = self._get_range_const_value(self.stmt.iter.args[1])
            start = LLLnode.from_list(arg0_val, typ=iter_typ, pos=getpos(self.stmt))
            rounds = LLLnode.from_list(arg1_val - arg0_val, typ=iter_typ, pos=getpos(self.stmt))


        else:
            arg1 = self.stmt.iter.args[1]
            rounds = self._get_range_const_value(arg1.right)
            start = Expr.parse_value_expr(arg0, self.context)

        r = rounds if isinstance(rounds, int) else rounds.value
        if r < 1:
            return

        varname = self.stmt.target.id
        pos = self.context.new_variable(varname, BaseType(iter_typ), pos=getpos(self.stmt))
        self.context.forvars[varname] = True
        lll_node = LLLnode.from_list(
            ["repeat", pos, start, rounds, parse_body(self.stmt.body, self.context)],
            typ=None,
            pos=getpos(self.stmt),
        )
        del self.context.forvars[varname]

        return lll_node
    def _parse_For_list(self):
        with self.context.range_scope():
            iter_list_node = Expr(self.stmt.iter, self.context).lll_node
        if not isinstance(iter_list_node.typ.subtype, BaseType):
