        o.extend(["_sym_subcode_size", begincode, "_mem_deploy_start", "CODECOPY"])


        o.extend(["_sym_subcode_size"] + PUSH(padding) + ["ADD"])
        o.extend(["_mem_deploy_start"])
        o.extend(["RETURN"])




