        o.extend(["ISZERO"])
        o.extend(_assert_false())
        return o

    elif code.value in CLAMP_OP_NAMES:
        if isinstance(code.args[0].value, int) and isinstance(code.args[1].value, int):


            args_0_val = code.args[0].value
            args_1_val = code.args[1].value
