                                "'dependencies_module': first in tuple "
                                "must be 'internal', 'pip-pypi', 'pip-git', "
                                "or 'apt'")

        if not error:

            unique_name = '{}.py'.format(input_info.INPUT_INFORMATION['input_name_unique'].lower())


