def script_run(request, scriptId, conn=None, **kwargs):
    """
    Runs a script using values in a POST
    """
    scriptService = conn.getScriptService()

    inputMap = {}

    sId = long(scriptId)

    try:
        params = scriptService.getParams(sId)
    except Exception as x:
        if x.message and x.message.startswith("No processor available"):

            rsp = run_script(request, conn, sId, inputMap, scriptName="Script")
            return JsonResponse(rsp)
        else:
            raise
    params = scriptService.getParams(sId)
    scriptName = params.name.replace("_", " ").replace(".py", "")

    logger.debug("Script: run with request.POST: %s" % request.POST)


    fileupload = (
        "file_annotation" in request.FILES and request.FILES["file_annotation"] or None
    )
    fileAnnId = None
    if fileupload is not None and fileupload != "":
        manager = BaseContainer(conn)
        fileAnnId = manager.createFileAnnotations(fileupload, [])

    for key, param in params.inputs.items():
        prototype = param.prototype
        pclass = prototype.__class__

        if key == "File_Annotation" and fileAnnId is not None:
            inputMap[key] = pclass(str(fileAnnId))
            continue



        if pclass == omero.rtypes.RBoolI:
            value = key in request.POST
            inputMap[key] = pclass(value)
            continue

        if pclass.__name__ == "RMapI":
            keyName = "%s_key0" % key
            valueName = "%s_value0" % key
            row = 0
            paramMap = {}
            while keyName in request.POST:


                k = str(request.POST[keyName])
                v = request.POST[valueName]
                if len(k) > 0 and len(v) > 0:
                    paramMap[str(k)] = v
                row += 1
                keyName = "%s_key%d" % (key, row)
                valueName = "%s_value%d" % (key, row)
            if len(paramMap) > 0:
                inputMap[key] = wrap(paramMap)
            continue

        if key in request.POST:
            if pclass == omero.rtypes.RListI:
                values = request.POST.getlist(key)
                if len(values) == 0:
                    continue
                if len(values) == 1:
                    if len(values[0]) == 0:
                        continue
                    values = values[0].split(",")


                listClass = omero.rtypes.RStringI
                pval = prototype.val


                if len(pval) > 0:
                    listClass = pval[0].__class__
                    if listClass == int(1).__class__:
                        listClass = omero.rtypes.rint
                    if listClass == long(1).__class__:
                        listClass = omero.rtypes.rlong


                valueList = []
                for v in values:
                    try:

                        obj = listClass(v.strip())
                    except Exception:
                        logger.debug("Invalid entry for '%s' : %s" % (key, v))
                        continue
                    if isinstance(obj, omero.model.IObject):
                        valueList.append(omero.rtypes.robject(obj))
                    else:
                        valueList.append(obj)
                inputMap[key] = omero.rtypes.rlist(valueList)


            else:
                value = request.POST[key]
                if len(value) == 0:
                    continue
                try:
                    inputMap[key] = pclass(value)
                except Exception:
                    logger.debug("Invalid entry for '%s' : %s" % (key, value))
                    continue



    if "IDs" in inputMap and "Data_Type" in inputMap:
        gid = conn.SERVICE_OPTS.getOmeroGroup()
        conn.SERVICE_OPTS.setOmeroGroup("-1")
        try:
            firstObj = conn.getObject(
                inputMap["Data_Type"].val, unwrap(inputMap["IDs"])[0]
            )
            newGid = firstObj.getDetails().group.id.val
            conn.SERVICE_OPTS.setOmeroGroup(newGid)
        except Exception:
            logger.debug(traceback.format_exc())

            conn.SERVICE_OPTS.setOmeroGroup(gid)

    try:

        logger.debug("Running script %s with " "params %s" % (scriptName, inputMap))
    except Exception:
        pass
    rsp = run_script(request, conn, sId, inputMap, scriptName)
    return JsonResponse(rsp)
logger = logging.getLogger(__name__)
def render_image_region(request, iid, z, t, conn=None, **kwargs):
    """
    Returns a jpeg of the OMERO image, rendering only a region specified in
    query string as region=x,y,width,height. E.g. region=0,512,256,256
    Rendering settings can be specified in the request parameters.

    @param request:     http request
    @param iid:         image ID
    @param z:           Z index
    @param t:           T index
    @param conn:        L{omero.gateway.BlitzGateway} connection
    @return:            http response wrapping jpeg
    """
    server_id = request.session["connector"].server_id






    pi = _get_prepared_image(request, iid, server_id=server_id, conn=conn)

    if pi is None:
        raise Http404
    img, compress_quality = pi

    tile = request.GET.get("tile", None)
    region = request.GET.get("region", None)
    level = None

    if tile:
        try:
            img._prepareRenderingEngine()
            w, h = img._re.getTileSize()
            levels = img._re.getResolutionLevels() - 1

            zxyt = tile.split(",")

            if len(zxyt) > 4:
                tile_size = [int(zxyt[3]), int(zxyt[4])]
                tile_defaults = [w, h]
                max_tile_length = 1024
                try:
                    max_tile_length = int(
                        conn.getConfigService().getConfigValue(
                            "omero.pixeldata.max_tile_length"
                        )
                    )
                except Exception:
                    pass
                for i, tile_length in enumerate(tile_size):

                    if tile_length <= 0:
                        tile_size[i] = tile_defaults[i]

                    if tile_length > max_tile_length:
                        tile_size[i] = max_tile_length
                w, h = tile_size
            v = int(zxyt[0])
            if v < 0:
                msg = "Invalid resolution level %s < 0" % v
                logger.debug(msg, exc_info=True)
                return HttpResponseBadRequest(msg)

            if levels == 0:
                if v > 0:
                    msg = "Invalid resolution level %s, non pyramid file" % v
                    logger.debug(msg, exc_info=True)
                    return HttpResponseBadRequest(msg)
                else:
                    level = None
            else:
                level = levels - v
                if level < 0:
                    msg = (
                        "Invalid resolution level, \
                    %s > number of available levels %s "
                        % (v, levels)
                    )
                    logger.debug(msg, exc_info=True)
                    return HttpResponseBadRequest(msg)
            x = int(zxyt[1]) * w
            y = int(zxyt[2]) * h
        except Exception:
            msg = "malformed tile argument, tile=%s" % tile
            logger.debug(msg, exc_info=True)
            return HttpResponseBadRequest(msg)
    elif region:
        try:
            xywh = region.split(",")

            x = int(xywh[0])
            y = int(xywh[1])
            w = int(xywh[2])
            h = int(xywh[3])
        except Exception:
            msg = "malformed region argument, region=%s" % region
            logger.debug(msg, exc_info=True)
            return HttpResponseBadRequest(msg)
    else:
        return HttpResponseBadRequest("tile or region argument required")


    jpeg_data = webgateway_cache.getImage(request, server_id, img, z, t)
    if jpeg_data is None:
        jpeg_data = img.renderJpegRegion(
            z, t, x, y, w, h, level=level, compression=compress_quality
        )
        if jpeg_data is None:
            raise Http404
        webgateway_cache.setImage(request, server_id, img, z, t, jpeg_data)

    rsp = HttpResponse(jpeg_data, content_type="image/jpeg")
    return rsp
def plateGrid_json(request, pid, field=0, conn=None, **kwargs):
    """
    Layout depends on settings 'omero.web.plate_layout' which
    can be overridden with request param e.g. ?layout=shrink.
    Use "expand" to expand to multiple of 8 x 12 grid
    Or "shrink" to remove rows/cols before first Well
    Or "trim" to neither expand nor shrink
    """
    try:
        field = long(field or 0)
    except ValueError:
        field = 0
    prefix = kwargs.get("thumbprefix", "webgateway_render_thumbnail")
    thumbsize = getIntOrDefault(request, "size", None)
    logger.debug(thumbsize)
    server_id = kwargs["server_id"]

    def get_thumb_url(iid):
        if thumbsize is not None:
            return reverse(prefix, args=(iid, thumbsize))
        return reverse(prefix, args=(iid,))

    layout = request.GET.get("layout")
    if layout not in ("shrink", "trim", "expand"):
        layout = settings.PLATE_LAYOUT

    plateGrid = PlateGrid(
        conn,
        pid,
        field,
        kwargs.get("urlprefix", get_thumb_url),
        plate_layout=layout,
    )

    plate = plateGrid.plate
    if plate is None:
        return Http404

    cache_key = "plategrid-%d-%s" % (field, thumbsize)
    rv = webgateway_cache.getJson(request, server_id, plate, cache_key)

    if rv is None:
        rv = plateGrid.metadata
        webgateway_cache.setJson(request, server_id, plate, json.dumps(rv), cache_key)
    else:
        rv = json.loads(rv)
    return rv
