def is_tuple_like(typ):


    ret = isinstance(typ, (TupleT, StructT))
    assert ret == hasattr(typ, "tuple_items")
    return ret
def is_array_like(typ):

    ret = isinstance(typ, (DArrayT, SArrayT))
