class TarArchiver(object):
    def __init__(self, dest, compression=''):
        assert compression in ['', 'gz', 'bz2']
        mode = "w|" + compression


        if isinstance(dest, str):
            self.z = tarfile.open(name=dest, mode=mode, encoding='UTF-8', format=tarfile.PAX_FORMAT)
            self.fileobj = None
        else:
            self.z = tarfile.open(fileobj=dest, mode=mode, encoding='UTF-8', format=tarfile.PAX_FORMAT)
            self.fileobj = dest
    def addfile(self, filename, arcname, encoding):
        assert isinstance(filename, bytes)
        assert isinstance(arcname, bytes)
        assert encoding

        if os.path.isdir(filename) and arcname == b'.':
            return


        filename = filename.decode('ascii', 'surrogateescape')

        arcname = arcname.decode(encoding, 'surrogateescape')

        self.z.add(filename, arcname, recursive=False)
class ZipArchiver(object):
    def addfile(self, filename, arcname, encoding):
        assert isinstance(filename, bytes)
        assert isinstance(arcname, bytes)
        assert encoding

        if os.path.isdir(filename) and arcname == b'.':
            return


        if os.path.islink(filename) or not (os.path.isfile(filename) or os.path.isdir(filename)):
            return

        filename = filename.decode('ascii', 'surrogateescape')


        arcname = arcname.decode(encoding, 'replace')

        self.z.write(filename, arcname)
class RawArchiver(object):
    def __init__(self, dest):
        assert dest
        self.dest = dest
        if isinstance(self.dest, str):
            self.output = open(self.dest, 'wb')
        else:
            self.outout = dest
    def addfile(self, filename, arcname, encoding):
        assert isinstance(filename, bytes)

        if os.path.isdir(filename):
            return
        with open(filename, 'rb') as f:
            shutil.copyfileobj(f, self.outout)
ARCHIVERS = {
def restore(restore, restore_as_of, kind, encoding, dest, log=logger.debug):
    """
    Used to restore a file or a directory.
    restore: relative or absolute file or folder to be restored (unquoted)
    restore_as_of: date to restore
    kind: type of archive to generate or raw to stream a single file.
    encoding: encoding of the repository (used to properly encode the filename in archive)
    dest: a filename or a file handler where to write the archive.
    """
    assert isinstance(restore, bytes)
    assert isinstance(restore_as_of, int)
    assert kind in ARCHIVERS



    tmp_output = tempfile.mkdtemp(prefix=b'rdiffweb_restore_')
    log('restoring data into temporary folder: %r' % tmp_output)


    rdiff_backup_path = find_rdiff_backup()




    env = {
        'LANG': LANG,
    }
    if os.environ.get('TMPDIR'):
        env['TMPDIR'] = os.environ['TMPDIR']

    cmd = [
        rdiff_backup_path,
        b'-v',
        b'5',
        b'--restore-as-of=' + str(restore_as_of).encode('latin'),
        restore,
        tmp_output,
    ]
    log('executing %r with env %r' % (cmd, env))


    archive = ARCHIVERS[kind](dest)
    try:

        with popen(cmd, env=env) as output:
            for line in output:
                line = line.rstrip(b'\n')
                log('rdiff-backup: %r' % line)
                if not line.startswith(TOKEN):
                    continue


                value = line[len(TOKEN) :]
                fullpath, arcname = _lookup_filename(tmp_output, line[len(TOKEN) :])
                if not fullpath:
                    log('error: file not found %r' % value)
                    continue


                log('adding %r' % fullpath)
                try:
                    archive.addfile(fullpath, arcname, encoding)
                except Exception:



                    log('error: fail to add %r' % fullpath, exc_info=1)


                if os.path.isfile(fullpath) or os.path.islink(fullpath):
                    os.remove(fullpath)
    finally:

        archive.close()

        if os.path.isdir(tmp_output):
            shutil.rmtree(tmp_output, ignore_errors=True)
        elif os.path.isfile(tmp_output):
            os.remove(tmp_output)
def main():
    parser = argparse.ArgumentParser(description='Rdiffweb restore script.')
    parser.add_argument('--restore-as-of', type=int, required=True)
    parser.add_argument('--encoding', type=str, default='utf-8', help='Define the encoding of the repository.')
    parser.add_argument(
        '--kind', type=str, choices=ARCHIVERS, default='zip', help='Define the type of archive to generate.'
    )
    parser.add_argument('restore', type=str, help='Define the path of the file or directory to restore.')
    parser.add_argument('output', type=str, default='-', help='Define the location of the archive. Default to stdout.')
    parser.add_argument('--version', action='version', version='%(prog)s ' + rdiffweb.__version__)
    args = parser.parse_args()

    path = args.restore
    if isinstance(path, str):
        path = os.fsencode(path)

    if args.output == '-':
        output = sys.stdout.buffer
    else:
        output = open(args.output, 'wb')

    try:
        restore(path, args.restore_as_of, args.kind, args.encoding, output, log=_print_stderr)
    except Exception:
        _print_stderr('error: failure to create the archive', exc_info=1)
        sys.exit(1)
def _split_path(path):
    """
    Split the given path into <username as str> / <path as bytes>
    """

    assert path
    if isinstance(path, str):
        path = os.fsencode(path)
    path = path.strip(b'/')
    if b'/' in path:
        username, path = path.split(b'/', 1)
        return username.decode('utf-8'), path
    else:
        return path.decode('utf-8'), b''
class UserObject(object):
    _ATTRS = ['username', 'role', 'email', 'user_root', 'password']
    def __init__(self, store, data):
        """
        Create a new UserObject from a username or a record.

        `data` a dict or a SQLAlchemy row.

        """
        assert store
        assert 'userid' in data
        self._store = store
        self._record = {k: data[k] for k in self._ATTRS}
        self._userid = data[_USERS.c.userid]
    def add_authorizedkey(self, key, comment=None):
        """
        Add the given key to the user. Adding the key to his `authorized_keys`
        file if it exists and adding it to database.
        """

        assert key
        key = authorizedkeys.check_publickey(key)


        key = authorizedkeys.AuthorizedKey(
            options=None, keytype=key.keytype, key=key.key, comment=comment or key.comment
        )


        filename = os.path.join(self.user_root, '.ssh', 'authorized_keys')
        if os.path.isfile(filename):
            with open(filename, mode="r+", encoding='utf-8') as fh:
                if authorizedkeys.exists(fh, key):
                    raise DuplicateSSHKeyError(_("SSH key already exists"))
                logger.info("add key [%s] to [%s] authorized_keys", key, self.username)
                authorizedkeys.add(fh, key)
        else:

            logger.info("add key [%s] to [%s] database", key, self.username)
            try:
                with self._store.engine.connect() as conn:
                    conn.execute(
                        _SSHKEYS.insert().values(userid=self._userid, fingerprint=key.fingerprint, key=key.getvalue())
                    )
            except IntegrityError:
                raise DuplicateSSHKeyError(
                    _("Duplicate key. This key already exists or is associated to another user.")
                )
        self._store.bus.publish('user_attr_changed', self, {'authorizedkeys': True})
    def delete(self):
        """
        Delete the given user from password store.

        Return True if the user was deleted.
        Return False if the user didn't exists.
        Raise a ValueError when trying to delete the admin user.
        """

        if self.username == self._store._admin_user:
            raise ValueError(_("can't delete admin user"))


        logger.info("deleting user [%s] from database", self.username)
        with self._store.engine.connect() as conn:
            conn.execute(_SSHKEYS.delete(_SSHKEYS.c.userid == self._userid))
            conn.execute(_REPOS.delete(_REPOS.c.userid == self._userid))
            deleted = conn.execute(_USERS.delete(_USERS.c.userid == self._userid))
            assert deleted.rowcount, 'fail to delete user'
        self._store.bus.publish('user_deleted', self.username)
        return True
    def delete_authorizedkey(self, fingerprint):
        """
        Remove the given key from the user. Remove the key from his
        `authorized_keys` file if it exists and from database database.
        """

        filename = os.path.join(self.user_root, '.ssh', 'authorized_keys')
        if os.path.isfile(filename):
            with open(filename, mode='r+', encoding='utf-8') as fh:
                logger.info("removing key [%s] from [%s] authorized_keys", fingerprint, self.username)
                authorizedkeys.remove(fh, fingerprint)
        else:

            logger.info("removing key [%s] from [%s] database", fingerprint, self.username)
            with self._store.engine.connect() as conn:
                conn.execute(
                    _SSHKEYS.delete(and_(_SSHKEYS.c.userid == self._userid, _SSHKEYS.c.fingerprint == fingerprint))
                )
