    assert os.path.exists(path), "%r doesn't exists" % path
    content_type = None
    if os.path.isfile(path):

        ext = ""
        i = path.rfind('.')
        if i != -1:
            ext = path[i:].lower()
        content_type = mimetypes.types_map.get(ext, None)

