        def __repr__(self):
            return "<no default>"
        def __bool__(self):
            raise TypeError("cannot convert {!r} to bool".format(self))
    class __INCOMPLETE:
        def __repr__(self):
            return "<incomplete value>"
        def __bool__(self):
            raise TypeError("cannot convert {!r} to bool".format(self))
