    async def _run_in_pool(self, query: str, args: t.Sequence[t.Any] = None):
        if args is None:
            args = []
        if not self.pool:
            raise ValueError("A pool isn't currently running.")

        async with self.pool.acquire() as connection:
            response = await connection.fetch(query, *args)

