            chunk_idx.add(archive_id, 1, len(data))
            archive = ArchiveItem(internal_dict=msgpack.unpackb(data))
            if archive.version not in (1, 2):
                raise Exception("Unknown archive metadata version")
            if archive.version == 1:
                items = archive.items
