                items = []
                for chunk_id, (csize, data) in zip(archive.item_ptrs, decrypted_repository.get_many(archive.item_ptrs)):
                    chunk_idx.add(chunk_id, 1, len(data))
                    ids = msgpack.unpackb(data)
